resolved AS (SELECT i.*, r.id AS rank_id, CASE WHEN upper(i.unit) LIKE '%STUDY LEAVE%' THEN 'study_leave'::staff_status ELSE 'active'::staff_status END AS status_v FROM incoming i LEFT JOIN public.ranks r ON upper(r.abbreviation)=upper(i.rank_abbr)),
matched AS (SELECT res.*, p.id AS existing_id FROM resolved res LEFT JOIN public.profiles p ON upper(p.first_name)=upper(res.first_name) AND upper(p.last_name)=upper(res.last_name)),
upd AS (UPDATE public.profiles p SET rank_id=COALESCE(m.rank_id,p.rank_id), gender=COALESCE(m.gender,p.gender), unit=COALESCE(NULLIF(m.unit,''),p.unit), shift_group=m.shift_group, status=m.status_v, updated_at=now() FROM matched m WHERE m.existing_id IS NOT NULL AND p.id=m.existing_id RETURNING p.id)
INSERT INTO public.profiles (staff_id, first_name, last_name, rank_id, gender, unit, shift_group, status, login_enabled)
SELECT m.staff_id, m.first_name, NULLIF(m.last_name,''), m.rank_id, m.gender, NULLIF(m.unit,''), m.shift_group, m.status_v, false
  FROM matched m WHERE m.existing_id IS NULL AND NOT EXISTS (SELECT 1 FROM public.profiles p2 WHERE p2.staff_id=m.staff_id);

